import{_ as e,C as d,o as t,c as r,a7 as i,b as h,w as s,a as l,E as p,a8 as o}from"./chunks/framework.BCbKzsgW.js";const B=JSON.parse('{"title":"库存管理：低库存提醒与补货判断","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/scenarios/inventory.md","filePath":"development/common/task-scheduling/scenarios/inventory.md","lastUpdated":1793441194000}'),E={name:"development/common/task-scheduling/scenarios/inventory.md"};function u(c,a,k,g,A,b){const n=d("Mermaid");return t(),r("div",null,[a[1]||(a[1]=i('<h1 id="ku-cun-guan-lidi-ku-cun-ti-xing-yu-bu-huo-pan-duan" tabindex="-1">库存管理：低库存提醒与补货判断 <a class="header-anchor" href="#ku-cun-guan-lidi-ku-cun-ti-xing-yu-bu-huo-pan-duan" aria-label="Permalink to &quot;库存管理：低库存提醒与补货判断&quot;">​</a></h1><p>低库存提醒可以由库存变更事件触发，再由周期扫描兜底。每次用户登录时遍历所有商品，既无法及时发现变化，也会把重复扫描压力放进请求链路。</p><p>示例以“仓库 + SKU”为库存对象，可售库存降到 100 以下触发告警，恢复到 120 以上才解除。两个阈值是示例，用来避免库存围绕一个阈值波动时不断开关告警。</p><h2 id="cong-yu-zhi-pan-duan-tui-dao-gao-jing-lun-ci" tabindex="-1">从阈值判断推导告警轮次 <a class="header-anchor" href="#cong-yu-zhi-pan-duan-tui-dao-gao-jing-lun-ci" aria-label="Permalink to &quot;从阈值判断推导告警轮次&quot;">​</a></h2><p>假设负责人要求“库存低于 100 就提醒补货”。如果每天只查看一次，小规模内部清单可以用周期摘要；如果需要变化后及时提醒，就应接续库存提交事件。</p><table tabindex="0"><thead><tr><th>候选方案</th><th>适合什么需求</th><th>需要处理的代价</th></tr></thead><tbody><tr><td>每天扫描并发送摘要</td><td>允许一天级别响应</td><td>变化不够及时，摘要需覆盖未处置对象</td></tr><tr><td>每次扣减都发送</td><td>确实要逐笔订阅库存事件</td><td>低库存持续期间会产生大量重复信息</td></tr><tr><td>维护低库存状态与告警轮次</td><td>需要提醒进入风险区间及后续处置</td><td>并发转换、恢复阈值和升级阶段</td></tr></tbody></table><p>本篇选择第三种：库存变更事实照常保留，通知只在约定状态转换或升级时产生。需要审计每一次瞬时缺货的业务，应在库存事务中记录转换事实，而不是只靠稍后读取当前库存。</p><h2 id="ku-cun-bian-hua-yu-gao-jing-de-zhi-xing-shi-xu" tabindex="-1">库存变化与告警的执行时序 <a class="header-anchor" href="#ku-cun-bian-hua-yu-gao-jing-de-zhi-xing-shi-xu" aria-label="Permalink to &quot;库存变化与告警的执行时序&quot;">​</a></h2><p>扣减或预留先形成库存事实，消费者再根据当前库存与规则维护告警。消息重复处理不应再次扣减库存。</p>',9)),(t(),h(o,null,{default:s(()=>[p(n,{id:"mermaid-74",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20%E5%BA%93%E5%AD%98%E6%8E%A5%E5%8F%A3%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20participant%20W%20as%20%E8%AF%84%E4%BC%B0%20Worker%0A%20%20%20%20participant%20C%20as%20%E9%80%9A%E7%9F%A5%E6%B8%A0%E9%81%93%0A%20%20%20%20A-%3E%3ED%3A%20%E5%90%8C%E4%BA%8B%E5%8A%A1%E6%9D%A1%E4%BB%B6%E9%A2%84%E7%95%99%E5%BA%93%E5%AD%98%3Cbr%3E%E4%BF%9D%E5%AD%98%E9%A2%84%E7%95%99%E4%B8%8E%E5%8F%98%E5%8C%96%E4%BA%8B%E4%BB%B6%0A%20%20%20%20D--%3E%3EA%3A%20%E6%8F%90%E4%BA%A4%E5%BA%93%E5%AD%98%E7%89%88%E6%9C%AC%0A%20%20%20%20W-%3E%3ED%3A%20%E9%A2%86%E5%8F%96%E4%BA%8B%E4%BB%B6%3Cbr%3E%E8%AF%BB%E5%8F%96%E5%BD%93%E5%89%8D%E5%BA%93%E5%AD%98%E3%80%81%E8%A7%84%E5%88%99%E4%B8%8E%E5%91%8A%E8%AD%A6%0A%20%20%20%20alt%20%E8%BF%9B%E5%85%A5%E6%96%B0%E7%9A%84%E4%BD%8E%E5%BA%93%E5%AD%98%E8%BD%AE%E6%AC%A1%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E5%90%8C%E4%BA%8B%E5%8A%A1%E5%BC%80%E5%90%AF%20episode%3Cbr%3E%E4%BF%9D%E5%AD%98%E9%80%9A%E7%9F%A5%E6%84%8F%E5%9B%BE%0A%20%20%20%20%20%20%20%20W-%3E%3EC%3A%20%E6%8C%89%E8%B4%9F%E8%B4%A3%E4%BA%BA%E5%88%86%E7%BB%84%E6%8F%90%E4%BA%A4%E6%8F%90%E9%86%92%0A%20%20%20%20%20%20%20%20C--%3E%3EW%3A%20%E6%8E%A5%E5%8F%97%E6%88%96%E5%A4%B1%E8%B4%A5%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E4%BF%9D%E5%AD%98%E6%B8%A0%E9%81%93%E7%BB%93%E6%9E%9C%0A%20%20%20%20else%20%E4%BB%8D%E5%9C%A8%E5%90%8C%E4%B8%80%E4%BD%8E%E5%BA%93%E5%AD%98%E8%BD%AE%E6%AC%A1%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E6%9B%B4%E6%96%B0%E8%A7%82%E5%AF%9F%E5%80%BC%3Cbr%3E%E4%B8%8D%E9%87%8D%E5%BB%BA%E5%90%8C%E9%98%B6%E6%AE%B5%E9%80%9A%E7%9F%A5%0A%20%20%20%20else%20%E8%BE%BE%E5%88%B0%E6%81%A2%E5%A4%8D%E6%9D%A1%E4%BB%B6%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E5%85%B3%E9%97%AD%E6%9C%AC%E8%BD%AE%3Cbr%3E%E6%8C%89%E8%A7%84%E5%88%99%E4%BF%9D%E5%AD%98%E6%81%A2%E5%A4%8D%E9%80%9A%E7%9F%A5%0A%20%20%20%20end%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i(`<p>图中的通知提交属于独立发送阶段，实际实现应在渠道调用前再次校验通知价值与负责人。采购审批和下单不由这次告警转换自动完成。</p><h2 id="xu-qiuzhuang-tai-yu-ze-ren-ren" tabindex="-1">需求、状态与责任人 <a class="header-anchor" href="#xu-qiuzhuang-tai-yu-ze-ren-ren" aria-label="Permalink to &quot;需求、状态与责任人&quot;">​</a></h2><p>低库存系统的目标是让负责补货的人得到可执行的信息，并保留缺口的处理进度。示例中普通消费者不接收库存告警，仓库负责人收到摘要，采购人员处理补货建议。</p><table tabindex="0"><thead><tr><th>业务问题</th><th>示例决策</th><th>实现落点</th></tr></thead><tbody><tr><td>什么时候算缺货风险</td><td>可售数量低于该仓库 SKU 的阈值</td><td>可版本化的规则记录</td></tr><tr><td>已经提醒后是否继续提醒</td><td>持续未处理时按升级周期再次提醒</td><td>告警轮次与升级阶段</td></tr><tr><td>规则或负责人改了怎么办</td><td>重新评估，之后通知新的有效负责人</td><td>规则变更事件、负责人查询</td></tr><tr><td>已有在途采购是否再采购</td><td>提醒可保留，采购建议先扣除可确认的在途量</td><td>建议与采购订单分离</td></tr><tr><td>什么时候算完成</td><td>告警恢复或明确处置，采购另有闭环</td><td>不用发送成功替代库存恢复</td></tr></tbody></table><h2 id="xian-que-ding-bi-jiao-na-zhong-ku-cun" tabindex="-1">先确定比较哪种库存 <a class="header-anchor" href="#xian-que-ding-bi-jiao-na-zhong-ku-cun" aria-label="Permalink to &quot;先确定比较哪种库存&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>是否直接用于示例提醒</th></tr></thead><tbody><tr><td>实物库存</td><td>不够，还要考虑已被预留的部分</td></tr><tr><td>预留库存</td><td>表示已占用、尚未完成出库的数量</td></tr><tr><td>可售库存</td><td>示例中比较的目标，计算规则需统一</td></tr><tr><td>在途采购</td><td>影响补货判断，但不应直接当成现货可售</td></tr></tbody></table><p>低库存告警与自动采购是不同动作。自动补货还要结合预测销量、采购提前期、在途数量、最小起订量和审批规则，不能简单地“低于 100 就下同一笔采购单”。</p><h2 id="shu-ju-mo-xing-yu-jie-kou" tabindex="-1">数据模型与接口 <a class="header-anchor" href="#shu-ju-mo-xing-yu-jie-kou" aria-label="Permalink to &quot;数据模型与接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>记录</th><th>关键字段与约束</th></tr></thead><tbody><tr><td><code>inventory_balances</code></td><td>仓库、SKU、实物、预留、库存版本；仓库与 SKU 唯一</td></tr><tr><td><code>stock_reservations</code></td><td>请求键、订单、预留量、状态；重复请求不重复预留</td></tr><tr><td><code>inventory_rules</code></td><td>阈值、恢复阈值、负责人规则、启用状态、版本</td></tr><tr><td><code>inventory_alerts</code></td><td>仓库 SKU、规则身份、当前状态、轮次、最近评估版本、升级阶段与下次升级时间</td></tr><tr><td><code>replenishment_suggestions</code></td><td>告警轮次、建议量、依据、处理状态、关联采购单</td></tr></tbody></table><p>扣减、预留释放和入库接口各自按业务流水幂等。规则修改接口保存版本并触发重新评估；告警确认接口记录谁接手处理，不把“已确认”当作库存已经恢复。</p><p>通知意图与渠道投递复用<a href="./batch-design.html#gong-yong-zhi-xing-yu-tong-zhi-yue-ding">共用通知约定</a>。意图保存告警轮次和通知阶段；每个接收目标、渠道的提交时间、结果与重试记录保存在投递层，不用告警表的一个“已通知时间”代替所有渠道的进度。</p><h2 id="ku-cun-geng-xin-de-shi-wu" tabindex="-1">库存更新的事务 <a class="header-anchor" href="#ku-cun-geng-xin-de-shi-wu" aria-label="Permalink to &quot;库存更新的事务&quot;">​</a></h2><p>下面用预留操作说明条件更新，<code>quantity</code> 必须为正数，库存对象还需经过仓库权限和启用状态校验：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> inventory_balances</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reserved </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reserved </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :quantity,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    stock_version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock_version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> warehouse_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :warehouse_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :sku_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :quantity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> on_hand </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reserved </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :quantity</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RETURNING warehouse_id, sku_id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          on_hand </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reserved </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> available,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          stock_version;</span></span></code></pre></div><p>请求资格确认、预留记录、库存更新和库存事件在同一事务提交。更新不到行时返回库存不足或对象状态错误；不要仍然建立成功预留记录。</p><p>on_hand - reserved &gt;= quantity 将可售约束放在实际写入时检查，stock_version 为后续评估标识新的库存事实。事件处理器不再扣减库存，是为了避免投递重试把同一笔预留重复执行。</p><p>释放只允许把未释放的预留转换一次，并在同一事务减少 reserved。事件消费者只处理告警，不再次扣减库存。</p><h2 id="zen-yang-chu-fa-yi-ci-gao-jing" tabindex="-1">怎样触发一次告警 <a class="header-anchor" href="#zen-yang-chu-fa-yi-ci-gao-jing" aria-label="Permalink to &quot;怎样触发一次告警&quot;">​</a></h2><p>扣减、预留释放、入库等操作提交时，在同一事务保存库存变化事件。消费者收到事件后，读取当前库存与告警状态，按状态机判断是否开启新一轮低库存告警。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常状态，库存 &lt; 100：开启告警轮次，保存通知意图</span></span>
<span class="line"><span>低库存状态，仍然 &lt; 120：更新观察值，不重复开启告警</span></span>
<span class="line"><span>低库存状态，库存 &gt;= 120：解除本轮告警</span></span>
<span class="line"><span>解除后再次 &lt; 100：开启新的告警轮次</span></span></code></pre></div><p>消费者并发时，需要条件更新或锁保护告警轮次；状态改变与通知意图一起提交。意图键可采用 <code>warehouse_id + sku + rule_id + alert_episode + stage</code>，渠道投递再按意图、渠道与接收目标去重。<code>stage</code> 区分首次低库存、各次升级和恢复，避免同一轮的后续合法通知被首次提醒的去重键拦住。</p><p>升级扫描按下次升级时间发现候选，在事务中复核本轮仍低库存、未被处理且已到升级时间，再推进阶段并保存对应意图。重复扫描命中同一阶段的意图；库存恢复则停止尚未提交的旧升级。升级阶段表示业务决定发送什么，实际是否提交成功仍看渠道记录。</p><p>事件与通知的持久化衔接可使用 <a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html" target="_blank" rel="noreferrer">Outbox 模式</a>。</p><h2 id="gao-jing-chu-li-qi-de-shi-wu" tabindex="-1">告警处理器的事务 <a class="header-anchor" href="#gao-jing-chu-li-qi-de-shi-wu" aria-label="Permalink to &quot;告警处理器的事务&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收到库存变化、规则变化事件，或兜底扫描命中对象</span></span>
<span class="line"><span>BEGIN</span></span>
<span class="line"><span>  按统一顺序锁定库存、规则所需记录与告警状态</span></span>
<span class="line"><span>  初始告警记录不存在时按唯一业务身份创建</span></span>
<span class="line"><span>  读取当前库存与当前规则，拒绝停用对象的旧动作</span></span>
<span class="line"><span>  根据正常或低库存状态决定开启、维持或恢复</span></span>
<span class="line"><span>  若开启：递增 episode，保存本轮通知意图</span></span>
<span class="line"><span>  若维持且达到升级条件：推进阶段，保存本阶段通知意图</span></span>
<span class="line"><span>  若恢复：关闭当前轮次，按规则保存恢复通知</span></span>
<span class="line"><span>  更新最近评估版本</span></span>
<span class="line"><span>COMMIT</span></span>
<span class="line"><span>通知 Worker 发送前核对本轮状态与当前负责人</span></span></code></pre></div><p>库存版本与规则版本都要参与判断。仅记录最近事件 ID，无法发现“库存没变，但阈值提高后已经低库存”的情况。</p><h2 id="1000-ci-kou-jian-zen-yang-bi-mian-fa-chu-1000-tiao-ti-xing" tabindex="-1">1000 次扣减怎样避免发出 1000 条提醒 <a class="header-anchor" href="#1000-ci-kou-jian-zen-yang-bi-mian-fa-chu-1000-tiao-ti-xing" aria-label="Permalink to &quot;1000 次扣减怎样避免发出 1000 条提醒&quot;">​</a></h2><p>如果 1000 次变化都属于同一个 SKU，消费者可以更新同一告警状态或合并待检查动作，最后只在阈值状态转换时生成通知。合并过程需要记录新版本或待处理标志，避免 Worker 运行期间到来的变化被提前清除。</p><p>如果 1000 个不同 SKU 同时低库存，则每个 SKU 保留独立告警记录，再按仓库、负责人和时间窗口汇总成摘要。摘要里保留明细入口，不能只给一个无法追踪的总数。</p><p>通知发送按渠道限速；库存变更本身不能等待整批邮件发送完成。</p><h2 id="ji-shi-shi-jian-yu-sao-miao-de-bian-jie" tabindex="-1">即时事件与扫描的边界 <a class="header-anchor" href="#ji-shi-shi-jian-yu-sao-miao-de-bian-jie" aria-label="Permalink to &quot;即时事件与扫描的边界&quot;">​</a></h2><p>消费者读取最新库存，可以避免迟到的旧事件把新状态覆盖回去。但如果库存短暂跌破阈值后立刻恢复，读取最新状态可能看不到这一瞬间。</p><p>若业务关心“当前是否需要补货”，读取当前状态通常符合目标；若需要记录每次缺货事件，就要在库存事务中保存阈值转换事实，不能依赖稍后读取最新值还原历史。</p><p>兜底扫描核对“当前低库存却没有活跃告警”的对象，以及“库存已恢复却仍有告警”的对象。它使用与事件消费者相同的状态转换逻辑。</p><h2 id="zhi-xing-bu-huo-dong-zuo-qian-zai-ci-pan-duan" tabindex="-1">执行补货动作前再次判断 <a class="header-anchor" href="#zhi-xing-bu-huo-dong-zuo-qian-zai-ci-pan-duan" aria-label="Permalink to &quot;执行补货动作前再次判断&quot;">​</a></h2><p>告警发出后，采购人员可能已经人工下单，或其他仓库完成调拨。自动采购任务开始前应检查在途订单和本轮告警是否仍有效，用业务约束阻止同一缺口重复下单。</p><p>通知成功只说明提醒流程完成，补货是否完成由采购与入库记录确认，两者应分别监控。</p><h2 id="yi-lun-ku-cun-bo-dong-de-ji-lu-yan-bian" tabindex="-1">一轮库存波动的记录演变 <a class="header-anchor" href="#yi-lun-ku-cun-bo-dong-de-ji-lu-yan-bian" aria-label="Permalink to &quot;一轮库存波动的记录演变&quot;">​</a></h2><p>假设仓库 W2 的 SKU K9 可售库存为 105，告警处于正常状态：</p><table tabindex="0"><thead><tr><th>变化</th><th>告警记录</th><th>通知行为</th></tr></thead><tbody><tr><td>预留 10，变为 95</td><td>开启 episode 12</td><td>建立本轮低库存意图</td></tr><tr><td>取消部分预留，变为 101</td><td>仍属于 episode 12</td><td>不因刚超过 100 就重复关闭和开启</td></tr><tr><td>再次扣减，变为 97</td><td>仍属于 episode 12</td><td>更新观察值，不新建同阶段通知</td></tr><tr><td>补货后变为 125</td><td>episode 12 恢复</td><td>按规则建立恢复通知</td></tr><tr><td>后续再次降到 90</td><td>开启 episode 13</td><td>可以产生新一轮低库存提醒</td></tr></tbody></table><p>库存版本标识每次数据变化，episode 标识一轮业务风险，两个计数不能共用。否则每次扣减都像新告警，或者恢复后的真实新风险被历史去重键永久拦住。</p><p>采购任务也不能仅凭 episode 自动下单：执行前要核对当前缺口、已有在途与审批结果，把“提醒存在”与“允许采购”分开判断。</p><h2 id="yan-shou-yu-pai-cha-yi-ju" tabindex="-1">验收与排查依据 <a class="header-anchor" href="#yan-shou-yu-pai-cha-yi-ju" aria-label="Permalink to &quot;验收与排查依据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>应断言的结果</th></tr></thead><tbody><tr><td>最后 5 件库存收到两个各预留 4 件的请求</td><td>最多一个成功，库存约束不被绕过</td></tr><tr><td>同一扣减事件重复 1000 次</td><td>不重复扣减，不重复开启同轮告警</td></tr><tr><td>库存在 99 与 101 之间波动</td><td>本轮告警保持，直到达到恢复条件</td></tr><tr><td>阈值从 100 提到 200，库存未变</td><td>规则事件或扫描触发重新评估</td></tr><tr><td>负责人变更、旧通知已排队</td><td>尚未发送的记录按当前规则处理</td></tr><tr><td>补货任务启动前已有采购单</td><td>重新计算缺口，避免同轮重复采购</td></tr></tbody></table><p>记录库存版本、规则版本、告警轮次与采购关联。监控低库存未处置年龄和通知延迟，不能只统计发送数量。</p><h2 id="tao-bao-kai-fang-ping-tai-de-di-ku-cun-shi-jian-bao-han-shi-me" tabindex="-1">淘宝开放平台的低库存事件包含什么 <a class="header-anchor" href="#tao-bao-kai-fang-ping-tai-de-di-ku-cun-shi-jian-bao-han-shi-me" aria-label="Permalink to &quot;淘宝开放平台的低库存事件包含什么&quot;">​</a></h2><p>淘宝开放平台公开了<a href="https://developer.alibaba.com/docs/topicDetail.htm?apiId=2728" target="_blank" rel="noreferrer">低库存预警消息</a>，其中包含商品、SKU、仓库、预警阈值与业务唯一键等属性，并说明部分消息接入有授权和白名单限制。这是一份外部事件协议，能够证明低库存风险可以作为业务事件传递，但没有公开其完整阈值计算、告警恢复或采购实现。</p><p>对照这个协议，库存提醒必须保留仓库与 SKU 维度；只按商品 ID 聚合会把不同仓库的缺货混在一起。接入外部预警后，本文建议先保存事件身份与来源，再核对当前库存和本地规则。外部业务键可以帮助接收去重，但不应直接当成本文的库存版本或告警轮次。</p><p>对于 1000 条预警，可以先按负责人和仓库形成摘要，同时保留每个 SKU 的独立处置记录；负责人点开摘要后仍能定位具体库存对象。接入权限不足时需采用获授权的查询或自身库存事件，不能默认所有商家都能订阅该消息。自动采购仍需单独审核在途量和采购身份，预警消息到达不构成采购已经获准。</p><h2 id="a-li-yun-tcc-jie-ruchao-shi-shi-fang-ke-neng-xian-yu-ku-cun-yu-liu-dao-da" tabindex="-1">阿里云 TCC 接入：超时释放可能先于库存预留到达 <a class="header-anchor" href="#a-li-yun-tcc-jie-ruchao-shi-shi-fang-ke-neng-xian-yu-ku-cun-yu-liu-dao-da" aria-label="Permalink to &quot;阿里云 TCC 接入：超时释放可能先于库存预留到达&quot;">​</a></h2><p>阿里云 SOFAStack 的 <a href="https://help.aliyun.com/zh/document_detail/132915.html" target="_blank" rel="noreferrer">TCC 防悬挂与幂等接入说明</a>讨论了二阶段回滚可能先于一阶段 Try 到达，以及同一事务的一阶段处理需要幂等的情况。这是框架接入机制；下面将其应用到库存预留场景，是本文的设计推导。</p><p>假设订单请求在网络中延迟，到期释放却先到库存服务。如果释放接口因为“查不到预留”就直接成功返回，迟到的预留随后仍可能扣占库存，形成永远等待确认的占用。业务需要为预留动作建立稳定身份，并用终止记录或框架的防悬挂机制阻止迟到请求重新生效。</p><table tabindex="0"><thead><tr><th>到达顺序</th><th>需要守住的结果</th></tr></thead><tbody><tr><td>预留成功，再收到取消</td><td>只释放该笔尚有效的预留</td></tr><tr><td>取消先到，预留后到</td><td>取消身份被保存，迟到预留不能重新占用</td></tr><tr><td>同一预留重复到达</td><td>不重复减少可售数量</td></tr><tr><td>同一取消重复到达</td><td>不重复增加可售数量</td></tr></tbody></table><p>这里的终止记录应覆盖最长允许的迟到与重放窗口。低库存提醒只是观察已确认的库存事实，不能靠再次执行扣减或释放来“修复”告警。若系统只用本地事务，不必为此引入整套 TCC，但仍需检查异步动作是否存在同样的先后竞争。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><p>阿里云 SOFAStack 官方接入说明：<a href="https://help.aliyun.com/zh/document_detail/132915.html" target="_blank" rel="noreferrer">TCC 防悬挂与幂等接入</a></p></li><li><p>淘宝开放平台官方协议：<a href="https://developer.alibaba.com/docs/topicDetail.htm?apiId=2728" target="_blank" rel="noreferrer">taobao_inventory_LowQuantityWarning：低库存预警消息</a></p></li><li><p>AWS Prescriptive Guidance：<a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html" target="_blank" rel="noreferrer">Transactional outbox pattern</a></p></li><li><p>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/transaction-iso.html" target="_blank" rel="noreferrer">并发更新与事务隔离</a></p></li><li><p>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/sql-update.html" target="_blank" rel="noreferrer">UPDATE</a></p></li></ul>`,56))])}const m=e(E,[["render",u]]);export{B as __pageData,m as default};
